function handler({
    api,
    event,
    helpers,
    imports
}) {

    async function showNotification() {
        api.emit('NOW_UXF_PAGE#ADD_NOTIFICATIONS', {
            "items": [{
                "id": 'ui_policy_notification',
                "status": "ai",
                "icon": "ai-sparkle-fill",
                "content": await helpers.translate('Some UI policies are generated by AI. Please review as needed'),
                "action": {
                    "type": "dismiss"
                }
            }]
        });
    }

    const {
        notification_handler_resource
    } = api.data;

    const output = notification_handler_resource?.output || {};
    const hasAiGeneratedRecords = output.hasAiGeneratedRecords || false;

    if (hasAiGeneratedRecords)
        showNotification();
}
